import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axiosInstance from '../config/axiosConfig';
import './Invoices.css';

const Invoices = () => {
  const { user } = useAuth();
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  
  useEffect(() => {
    const fetchInvoices = async () => {
      try {
        setLoading(true);
        const response = await axiosInstance.get('/api/invoices');
        setInvoices(response.data || []);
      } catch (err) {
        console.error('Error fetching invoices:', err);
        setError('Failed to fetch invoices. Please check the All Invoices page for complete functionality.');
      } finally {
        setLoading(false);
      }
    };
    
    fetchInvoices();
  }, [user]);
  
  // Count invoice statistics
  const calculateStats = () => {
    let total = invoices.length;
    let pending = invoices.filter(inv => inv.status === 'pending').length;
    let paid = invoices.filter(inv => inv.status === 'paid').length;
    
    return { total, pending, paid };
  };
  
  const stats = calculateStats();
  
  if (loading) {
    return <div className="dashboard-content-container invoices-loading">Loading invoices...</div>;
  }
  
  if (error) {
    return (
      <div className="dashboard-content-container invoices-error">
        <p>{error}</p>
        <Link to="/all-invoices" className="invoices-link">
          Go to All Invoices
        </Link>
      </div>
    );
  }
  
  // If no invoices were loaded, suggest the all-invoices page
  if (invoices.length === 0) {
    return (
      <div className="dashboard-content-container invoices-page">
        <div className="invoices-header">
          <div className="header-content">
            <div className="header-left">
              <h1>Invoices</h1>
              <p>No invoices found. Create your first invoice to get started.</p>
            </div>
            <Link to="/create-invoice" className="create-invoice-btn">
              Create Invoice
            </Link>
          </div>
        </div>
      </div>
    );
  }
  
  return (
    <div className="dashboard-content-container invoices-page">
      <div className="invoices-header">
        <div className="header-content">
          <div className="header-left">
            <h1>Invoices</h1>
            <div className="invoice-stats">
              <div className="stat">
                <span className="stat-value">{stats.total}</span>
                <span className="stat-label">Total</span>
              </div>
              <div className="stat pending">
                <span className="stat-value">{stats.pending}</span>
                <span className="stat-label">Pending</span>
              </div>
              <div className="stat paid">
                <span className="stat-value">{stats.paid}</span>
                <span className="stat-label">Paid</span>
              </div>
            </div>
          </div>
          <div className="header-right">
            <Link to="/all-invoices" className="view-all-btn">View All</Link>
            <Link to="/create-invoice" className="create-invoice-btn">Create Invoice</Link>
          </div>
        </div>
      </div>

      <div className="invoices-content">
        <div className="invoices-grid">
          {invoices.map(invoice => (
            <div key={invoice.id} className="invoice-card">
              <div className="invoice-header">
                <div className="invoice-number">#{invoice.invoiceNumber || invoice.id.substring(0, 8)}</div>
                <div className={`invoice-status ${invoice.status}`}>{invoice.status}</div>
              </div>
              
              <div className="invoice-details">
                <div className="client-name">
                  <span className="label">Client:</span>
                  <span>{invoice.clientName || "Client"}</span>
                </div>
                <div className="amount">
                  <span className="label">Amount:</span>
                  <span className="value">₹{invoice.totalAmount || "0.00"}</span>
                </div>
                <div className="dates">
                  <div className="issue-date">
                    <span className="label">Issued:</span>
                    <span>{invoice.issueDate ? new Date(invoice.issueDate).toLocaleDateString() : "N/A"}</span>
                  </div>
                  <div className="due-date">
                    <span className="label">Due:</span>
                    <span>{invoice.dueDate ? new Date(invoice.dueDate).toLocaleDateString() : "N/A"}</span>
                  </div>
                </div>
              </div>
              
              <div className="invoice-actions">
                <Link to={`/invoice/${invoice.id}`} className="action-btn view">View</Link>
                <Link to={`/edit-invoice/${invoice.id}`} className="action-btn edit">Edit</Link>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Invoices; 