import React, { useState, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogActions,
  TextField,
  Button,
  Grid,
  MenuItem,
  CircularProgress,
  FormHelperText,
  FormControl,
  InputLabel,
  Select,
  Typography,
  Box,
  IconButton,
} from '@mui/material';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { AdapterDateFns } from '@mui/x-date-pickers/AdapterDateFns';
import { LocalizationProvider } from '@mui/x-date-pickers/LocalizationProvider';
import CloseIcon from '@mui/icons-material/Close';
import CalendarTodayOutlinedIcon from '@mui/icons-material/CalendarTodayOutlined';
import BusinessOutlinedIcon from '@mui/icons-material/BusinessOutlined';
import AssignmentOutlinedIcon from '@mui/icons-material/AssignmentOutlined';
import AttachMoneyOutlinedIcon from '@mui/icons-material/AttachMoneyOutlined';
import InsertDriveFileOutlinedIcon from '@mui/icons-material/InsertDriveFileOutlined';
import NotesOutlinedIcon from '@mui/icons-material/NotesOutlined';
import LinkOutlinedIcon from '@mui/icons-material/LinkOutlined';
import { axiosInstance } from '../../contexts/AuthContext';

const projectStatuses = ['Not Started', 'In Progress', 'Completed'];
const paymentStatuses = ['Pending', 'Partial', 'Paid'];

// Brand color palette
const brandColors = {
  primary: '#002619',   // Darker green for main elements
  secondary: '#4CAF50', // Green accent for highlights
  accent: '#80CBC4',    // Light teal for subtle accents
  light: '#EEF7F6',     // Very light background tint
  text: '#202020',      // Near-black for text
  lightGrey: '#f9fafb', // Light grey for backgrounds
  border: '#e5e7eb',    // Border color
};

export default function AddProjectForm({ open, onClose, onSubmit }) {
  const [formData, setFormData] = useState({
    clientName: '',
    projectName: '',
    numberOfFiles: '',
    unitPrice: '',
    projectStatus: 'Not Started',
    paymentStatus: 'Pending',
    notes: '',
    links: '',
    startDate: null,
    endDate: null,
  });
  const [errors, setErrors] = useState({});
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(false);
  const [clientError, setClientError] = useState('');

  // Fetch clients when the form opens
  useEffect(() => {
    if (open) {
      fetchClients();
    }
  }, [open]);

  const fetchClients = async () => {
    setLoading(true);
    setClientError('');
    try {
      const response = await axiosInstance.get('/api/clients');
      setClients(response.data);
    } catch (error) {
      console.error('Error fetching clients:', error);
      setClientError('Failed to load clients. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
    // Clear error when user types
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const handleDateChange = (name, date) => {
    setFormData(prev => ({
      ...prev,
      [name]: date
    }));
    // Clear date error if any
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: ''
      }));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.clientName.trim()) {
      newErrors.clientName = 'Client name is required';
    }
    if (!formData.projectName.trim()) {
      newErrors.projectName = 'Project name is required';
    }
    if (!formData.numberOfFiles || formData.numberOfFiles <= 0) {
      newErrors.numberOfFiles = 'Number of files must be greater than 0';
    }
    if (formData.numberOfFiles > 1000000) {
      newErrors.numberOfFiles = 'Number of files cannot exceed 1,000,000';
    }
    if (!formData.unitPrice || formData.unitPrice <= 0) {
      newErrors.unitPrice = 'Unit price must be greater than 0';
    }
    if (formData.unitPrice > 1000000) {
      newErrors.unitPrice = 'Unit price cannot exceed 1,000,000';
    }
    const total = Number(formData.numberOfFiles) * Number(formData.unitPrice);
    if (total > 999999999.99) {
      newErrors.unitPrice = 'Total amount would exceed maximum allowed value';
    }
    
    // Validate links if provided
    if (formData.links && !isValidLinks(formData.links)) {
      newErrors.links = 'Please enter valid URLs separated by commas or new lines';
    }

    // Validate end date is after start date if both provided
    if (formData.startDate && formData.endDate && new Date(formData.endDate) < new Date(formData.startDate)) {
      newErrors.endDate = 'End date must be after start date';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };
  
  const isValidLinks = (links) => {
    if (!links.trim()) return true;
    
    // Split by commas or new lines
    const linkArray = links.split(/[\n,]+/).map(link => link.trim()).filter(link => link);
    
    // Simple URL validation
    const urlPattern = /^(https?:\/\/)?([\da-z.-]+)\.([a-z.]{2,6})([/\w .-]*)*\/?$/;
    return linkArray.every(link => urlPattern.test(link));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validateForm()) {
      const total = Number(formData.numberOfFiles) * Number(formData.unitPrice);
      onSubmit({
        ...formData,
        numberOfFiles: Number(formData.numberOfFiles),
        unitPrice: Number(formData.unitPrice),
        total
      });
      // Reset form data
      setFormData({
        clientName: '',
        projectName: '',
        numberOfFiles: '',
        unitPrice: '',
        projectStatus: 'Not Started',
        paymentStatus: 'Pending',
        notes: '',
        links: '',
        startDate: null,
        endDate: null,
      });
      setErrors({});
      onClose();
    }
  };

  // Text field styling
  const textFieldStyle = {
    '& .MuiOutlinedInput-root': {
      borderRadius: '8px',
      '&:hover fieldset': {
        borderColor: brandColors.accent,
      },
      '&.Mui-focused fieldset': {
        borderColor: brandColors.secondary,
      }
    },
    '& .MuiInputLabel-root': {
      color: brandColors.text,
    },
    '& .MuiInputLabel-root.Mui-focused': {
      color: brandColors.secondary,
    },
    '& .MuiInputAdornment-root': {
      color: brandColors.text,
    }
  };

  // Select field styling
  const selectFieldStyle = {
    ...textFieldStyle,
    '& .MuiSelect-select': {
      paddingLeft: '12px',
    }
  };

  return (
    <Dialog 
      open={open} 
      onClose={onClose} 
      maxWidth="md" 
      fullWidth
      PaperProps={{
        sx: {
          borderRadius: '12px',
          boxShadow: '0 8px 24px rgba(0, 38, 25, 0.12)',
          overflow: 'hidden',
          display: 'flex',
          flexDirection: 'column',
          maxHeight: '90vh'
        }
      }}
    >
      <Box sx={{ 
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        borderBottom: `1px solid ${brandColors.border}`,
        padding: '16px 24px',
        backgroundColor: brandColors.primary,
        zIndex: 1
      }}>
        <Typography variant="h5" sx={{ fontWeight: 600, color: 'white' }}>
          Add New Project
        </Typography>
        <IconButton onClick={onClose} size="small" sx={{ color: 'white' }}>
          <CloseIcon />
        </IconButton>
      </Box>
      
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', height: '100%' }}>
        <DialogContent 
          sx={{ 
            padding: '24px', 
            overflow: 'auto',
            flex: 1
          }}
        >
          <Grid container spacing={3}>
            {/* Client Select */}
            <Grid item xs={12}>
              <FormControl fullWidth error={!!errors.clientName} sx={selectFieldStyle}>
                <InputLabel id="client-select-label">Client *</InputLabel>
                <Select
                  labelId="client-select-label"
                  id="client-select"
                  name="clientName"
                  value={formData.clientName}
                  onChange={handleChange}
                  label="Client *"
                  required
                  disabled={loading}
                  startAdornment={
                    <BusinessOutlinedIcon sx={{ color: '#333', mr: 1, ml: 1 }} />
                  }
                >
                  {loading ? (
                    <MenuItem disabled>
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        <CircularProgress size={20} />
                        <Typography>Loading clients...</Typography>
                      </Box>
                    </MenuItem>
                  ) : clients.length > 0 ? (
                    clients.map((client) => (
                      <MenuItem key={client.id} value={client.name}>
                        {client.name}
                      </MenuItem>
                    ))
                  ) : (
                    <MenuItem disabled>No clients available</MenuItem>
                  )}
                </Select>
                {errors.clientName && <FormHelperText>{errors.clientName}</FormHelperText>}
                {clientError && <FormHelperText error>{clientError}</FormHelperText>}
              </FormControl>
            </Grid>

            {/* Project Name */}
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Project Name *"
                name="projectName"
                value={formData.projectName}
                onChange={handleChange}
                error={!!errors.projectName}
                helperText={errors.projectName}
                required
                sx={textFieldStyle}
                InputProps={{
                  startAdornment: (
                    <AssignmentOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                  ),
                }}
              />
            </Grid>

            {/* Number of Files and Unit Price */}
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Number of Files *"
                name="numberOfFiles"
                type="number"
                value={formData.numberOfFiles}
                onChange={handleChange}
                error={!!errors.numberOfFiles}
                helperText={errors.numberOfFiles}
                required
                sx={textFieldStyle}
                InputProps={{
                  startAdornment: (
                    <InsertDriveFileOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                  ),
                }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Unit Price *"
                name="unitPrice"
                type="number"
                value={formData.unitPrice}
                onChange={handleChange}
                error={!!errors.unitPrice}
                helperText={errors.unitPrice}
                required
                sx={textFieldStyle}
                InputProps={{
                  startAdornment: (
                    <AttachMoneyOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                  ),
                }}
              />
            </Grid>

            {/* Start Date and End Date */}
            <Grid item xs={12} sm={6}>
              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <DatePicker
                  label="Start Date"
                  value={formData.startDate}
                  onChange={(newDate) => handleDateChange('startDate', newDate)}
                  format="dd/MM/yyyy"
                  slotProps={{
                    textField: {
                      fullWidth: true,
                      error: !!errors.startDate,
                      helperText: errors.startDate,
                      sx: textFieldStyle,
                      InputProps: {
                        startAdornment: (
                          <CalendarTodayOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                        ),
                      }
                    }
                  }}
                />
              </LocalizationProvider>
            </Grid>
            <Grid item xs={12} sm={6}>
              <LocalizationProvider dateAdapter={AdapterDateFns}>
                <DatePicker
                  label="End Date"
                  value={formData.endDate}
                  onChange={(newDate) => handleDateChange('endDate', newDate)}
                  format="dd/MM/yyyy"
                  slotProps={{
                    textField: {
                      fullWidth: true,
                      error: !!errors.endDate,
                      helperText: errors.endDate,
                      sx: textFieldStyle,
                      InputProps: {
                        startAdornment: (
                          <CalendarTodayOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                        ),
                      }
                    }
                  }}
                />
              </LocalizationProvider>
            </Grid>

            {/* Project Status and Payment Status */}
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth sx={selectFieldStyle}>
                <InputLabel id="project-status-label">Project Status</InputLabel>
                <Select
                  labelId="project-status-label"
                  id="project-status"
                  name="projectStatus"
                  value={formData.projectStatus}
                  onChange={handleChange}
                  label="Project Status"
                >
                  {projectStatuses.map((status) => (
                    <MenuItem key={status} value={status}>
                      {status}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth sx={selectFieldStyle}>
                <InputLabel id="payment-status-label">Payment Status</InputLabel>
                <Select
                  labelId="payment-status-label"
                  id="payment-status"
                  name="paymentStatus"
                  value={formData.paymentStatus}
                  onChange={handleChange}
                  label="Payment Status"
                >
                  {paymentStatuses.map((status) => (
                    <MenuItem key={status} value={status}>
                      {status}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>

            {/* Notes */}
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Notes"
                name="notes"
                value={formData.notes}
                onChange={handleChange}
                multiline
                rows={3}
                sx={textFieldStyle}
                InputProps={{
                  startAdornment: (
                    <Box sx={{ display: 'flex', alignItems: 'flex-start', pt: 1.5, height: '100%' }}>
                      <NotesOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                    </Box>
                  ),
                }}
              />
            </Grid>

            {/* Links */}
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Links (separate by commas or new lines)"
                name="links"
                value={formData.links}
                onChange={handleChange}
                error={!!errors.links}
                helperText={errors.links || "Add URLs to related resources, files, or references"}
                multiline
                rows={2}
                sx={textFieldStyle}
                InputProps={{
                  startAdornment: (
                    <Box sx={{ display: 'flex', alignItems: 'flex-start', pt: 1.5, height: '100%' }}>
                      <LinkOutlinedIcon sx={{ color: '#333', mr: 1 }} />
                    </Box>
                  ),
                }}
              />
            </Grid>
          </Grid>
        </DialogContent>

        <DialogActions sx={{ 
          padding: '16px 24px', 
          borderTop: `1px solid ${brandColors.border}`,
          backgroundColor: brandColors.lightGrey,
          display: 'flex',
          justifyContent: 'flex-end',
          gap: 2,
          position: 'sticky',
          bottom: 0,
          zIndex: 1
        }}>
          <Button 
            onClick={onClose} 
            sx={{ 
              color: brandColors.text, 
              borderRadius: '8px',
              textTransform: 'none',
              fontWeight: 500,
            }}
          >
            Cancel
          </Button>
          <Button 
            type="submit" 
            variant="contained" 
            sx={{ 
              bgcolor: brandColors.primary, 
              color: 'white', 
              borderRadius: '8px',
              '&:hover': {
                bgcolor: '#0d3629',
              },
              textTransform: 'none',
              fontWeight: 600,
              padding: '8px 20px',
              boxShadow: '0 4px 12px rgba(0, 38, 25, 0.25)'
            }}
          >
            Add Project
          </Button>
        </DialogActions>
      </form>
    </Dialog>
  );
} 