import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  Box,
  Typography,
  Paper,
  Grid,
  Button,
  CircularProgress,
  Alert,
  Divider,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Snackbar,
  Card,
  CardContent,
  Chip,
  useTheme,
  alpha,
  Tooltip,
  IconButton,
} from '@mui/material';
import {
  ArrowBack as ArrowBackIcon,
  GetApp as DownloadIcon,
  Receipt as ReceiptIcon,
  Business as BusinessIcon,
  Person as PersonIcon,
  CalendarToday as CalendarIcon,
  AttachMoney as MoneyIcon,
  Edit as EditIcon,
} from '@mui/icons-material';
import axiosInstance from '../config/axiosConfig';
import { useAuth } from '../contexts/AuthContext';

export default function InvoiceDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();
  const theme = useTheme();
  const [invoice, setInvoice] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  useEffect(() => {
    fetchInvoice();
  }, [id, user]);

  const fetchInvoice = async () => {
    try {
      setLoading(true);
      const response = await axiosInstance.get(`/api/invoices/${id}`);
      setInvoice(response.data);
      setError(null);
    } catch (error) {
      console.error('Error fetching invoice:', error);
      setError('Failed to fetch invoice details. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadInvoice = async () => {
    try {
      const response = await axiosInstance.get(`/api/invoices/${id}/download`, {
        responseType: 'blob'
      });
      
      // Create a blob URL and trigger download
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `invoice-${invoice.invoice_number}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      
      setNotification({
        open: true,
        message: 'Invoice downloaded successfully!',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error downloading invoice:', error);
      setNotification({
        open: true,
        message: 'Failed to download invoice',
        severity: 'error'
      });
    }
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({
      ...prev,
      open: false
    }));
  };

  // Format date from ISO string to local date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    
    try {
      // Handle both ISO dates and DD-MM-YYYY format
      let date;
      if (dateString.includes('-') && dateString.includes('T')) {
        // ISO format
        date = new Date(dateString);
      } else if (dateString.includes('-') && dateString.split('-').length === 3) {
        // DD-MM-YYYY format
        const [day, month, year] = dateString.split('-');
        date = new Date(year, month - 1, day);
      } else {
        return dateString; // Return as is if format is unknown
      }
      
      return date.toLocaleDateString();
    } catch (error) {
      console.error('Error formatting date:', error);
      return dateString; // Return original string if there's an error
    }
  };

  // Get items array from invoice data
  const getInvoiceItems = () => {
    if (!invoice || !invoice.items) return [];
    
    if (Array.isArray(invoice.items)) {
      return invoice.items;
    } else if (invoice.items.items && Array.isArray(invoice.items.items)) {
      return invoice.items.items;
    }
    
    return [];
  };

  // Get GST rate from invoice data
  const getGstRate = () => {
    if (!invoice) return 18;
    
    if (invoice.items && typeof invoice.items === 'object' && invoice.items.metadata && invoice.items.metadata.gstRate) {
      return invoice.items.metadata.gstRate;
    }
    
    return 18;
  };

  // Get CGST rate from invoice data
  const getCgstRate = () => {
    if (!invoice) return 9;
    
    if (invoice.items && typeof invoice.items === 'object' && invoice.items.metadata && invoice.items.metadata.cgstRate) {
      return invoice.items.metadata.cgstRate;
    }
    
    return 9;
  };

  // Get SGST rate from invoice data
  const getSgstRate = () => {
    if (!invoice) return 9;
    
    if (invoice.items && typeof invoice.items === 'object' && invoice.items.metadata && invoice.items.metadata.sgstRate) {
      return invoice.items.metadata.sgstRate;
    }
    
    return 9;
  };

  // Get CGST amount
  const getCgstAmount = () => {
    if (!invoice) return 0;
    
    if (invoice.cgst) {
      return parseFloat(invoice.cgst);
    }
    
    // If cgst is not separately stored, use half of the total GST
    return parseFloat(invoice.gst) / 2;
  };

  // Get SGST amount
  const getSgstAmount = () => {
    if (!invoice) return 0;
    
    if (invoice.sgst) {
      return parseFloat(invoice.sgst);
    }
    
    // If sgst is not separately stored, use half of the total GST
    return parseFloat(invoice.gst) / 2;
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}>
        <CircularProgress size={60} thickness={4} />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ mt: 4, p: 3, textAlign: 'center' }}>
        <Alert 
          severity="error" 
          sx={{ 
            mb: 3, 
            maxWidth: 600, 
            mx: 'auto',
            '& .MuiAlert-icon': { fontSize: '2rem' }
          }}
        >
          {error}
        </Alert>
        <Button 
          variant="contained" 
          size="large"
          onClick={fetchInvoice}
          sx={{ mt: 2 }}
        >
          Retry
        </Button>
      </Box>
    );
  }

  if (!invoice) {
    return (
      <Box sx={{ mt: 4, p: 3, textAlign: 'center' }}>
        <Alert 
          severity="warning" 
          sx={{ 
            mb: 3, 
            maxWidth: 600, 
            mx: 'auto',
            '& .MuiAlert-icon': { fontSize: '2rem' }
          }}
        >
          Invoice not found
        </Alert>
        <Button 
          variant="contained" 
          size="large"
          onClick={() => navigate('/invoices')}
          startIcon={<ArrowBackIcon />}
          sx={{ mt: 2 }}
        >
          Back to Invoices
        </Button>
      </Box>
    );
  }

  return (
    <Box>
      <Box sx={{ mb: 4 }}>
        <Typography 
          variant="h4" 
          sx={{ 
            fontWeight: 700, 
            mb: 1,
            background: `linear-gradient(90deg, ${theme.palette.primary.main} 0%, ${theme.palette.secondary.main} 100%)`,
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          Invoice Details
        </Typography>
        <Typography variant="body1" color="text.secondary">
          View and manage invoice information
        </Typography>
      </Box>

      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Button
          variant="outlined"
          startIcon={<ArrowBackIcon />}
          onClick={() => navigate('/invoices')}
          sx={{ 
            borderRadius: '8px',
            borderWidth: '1.5px',
            '&:hover': {
              borderWidth: '1.5px',
            }
          }}
        >
          Back to Invoices
        </Button>
        <Box sx={{ display: 'flex', gap: 2 }}>
          <Button
            variant="outlined"
            startIcon={<EditIcon />}
            onClick={() => navigate(`/edit-invoice/${id}`)}
            sx={{ 
              borderRadius: '8px',
              borderWidth: '1.5px',
              '&:hover': {
                borderWidth: '1.5px',
              }
            }}
          >
            Edit Invoice
          </Button>
          <Button
            variant="contained"
            startIcon={<DownloadIcon />}
            onClick={handleDownloadInvoice}
            sx={{ 
              px: 3, 
              py: 1.2,
              boxShadow: '0px 4px 10px rgba(37, 99, 235, 0.2)',
              '&:hover': {
                boxShadow: '0px 6px 15px rgba(37, 99, 235, 0.3)',
              }
            }}
          >
            Download PDF
          </Button>
        </Box>
      </Box>

      {/* Invoice Header Card */}
      <Card 
        sx={{ 
          mb: 4, 
          overflow: 'visible',
          position: 'relative',
          '&::before': {
            content: '""',
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            height: '8px',
            background: `linear-gradient(90deg, ${theme.palette.primary.main} 0%, ${theme.palette.secondary.main} 100%)`,
            borderTopLeftRadius: '12px',
            borderTopRightRadius: '12px',
          }
        }}
      >
        <CardContent sx={{ p: 3, pt: 4 }}>
          <Grid container spacing={3}>
            <Grid item xs={12} md={6}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Box 
                  sx={{ 
                    width: 40, 
                    height: 40, 
                    borderRadius: '8px', 
                    bgcolor: alpha(theme.palette.primary.main, 0.1),
                    color: theme.palette.primary.main,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    mr: 2
                  }}
                >
                  <ReceiptIcon />
                </Box>
                <Typography variant="h5" fontWeight={600}>
                  Invoice #{invoice.invoice_number}
                </Typography>
              </Box>
              <Chip 
                label="Issued" 
                color="success" 
                size="small" 
                sx={{ 
                  fontWeight: 500, 
                  borderRadius: '6px',
                  mb: 2
                }} 
              />
            </Grid>
            <Grid item xs={12} md={6} sx={{ display: 'flex', justifyContent: { xs: 'flex-start', md: 'flex-end' } }}>
              <Box sx={{ textAlign: { xs: 'left', md: 'right' } }}>
                <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>
                  Invoice Date
                </Typography>
                <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: { xs: 'flex-start', md: 'flex-end' } }}>
                  <CalendarIcon fontSize="small" sx={{ color: theme.palette.text.secondary, mr: 1 }} />
                  <Typography variant="body1" fontWeight={500}>
                    {formatDate(invoice.date)}
                  </Typography>
                </Box>
              </Box>
            </Grid>
          </Grid>

          <Divider sx={{ my: 3 }} />

          <Grid container spacing={4}>
            <Grid item xs={12} md={6}>
              <Box>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <BusinessIcon fontSize="small" sx={{ color: theme.palette.primary.main, mr: 1 }} />
                  <Typography variant="subtitle1" fontWeight={600}>From</Typography>
                </Box>
                <Box sx={{ 
                  p: 2, 
                  borderRadius: '8px', 
                  bgcolor: alpha(theme.palette.primary.main, 0.05),
                  border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
                }}>
                  <Typography variant="body1" fontWeight={500}>{invoice.company_name}</Typography>
                </Box>
              </Box>
            </Grid>
            <Grid item xs={12} md={6}>
              <Box>
                <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                  <PersonIcon fontSize="small" sx={{ color: theme.palette.secondary.main, mr: 1 }} />
                  <Typography variant="subtitle1" fontWeight={600}>To</Typography>
                </Box>
                <Box sx={{ 
                  p: 2, 
                  borderRadius: '8px', 
                  bgcolor: alpha(theme.palette.secondary.main, 0.05),
                  border: `1px solid ${alpha(theme.palette.secondary.main, 0.1)}`,
                }}>
                  <Typography variant="body1" fontWeight={500}>{invoice.client_name}</Typography>
                </Box>
              </Box>
            </Grid>
          </Grid>
        </CardContent>
      </Card>

      {/* Invoice Items */}
      <Card sx={{ mb: 4 }}>
        <CardContent sx={{ p: 0 }}>
          <Box sx={{ p: 3, pb: 2 }}>
            <Typography variant="h6" fontWeight={600} sx={{ mb: 1 }}>
              Invoice Items
            </Typography>
            <Typography variant="body2" color="text.secondary">
              Products and services included in this invoice
            </Typography>
          </Box>
          
          <TableContainer>
            <Table>
              <TableHead>
                <TableRow sx={{ bgcolor: alpha(theme.palette.primary.main, 0.03) }}>
                  <TableCell sx={{ fontWeight: 600, py: 2 }}>Description</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 600, py: 2 }}>Quantity</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 600, py: 2 }}>Rate</TableCell>
                  <TableCell align="right" sx={{ fontWeight: 600, py: 2 }}>Amount</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {getInvoiceItems().map((item, index) => (
                  <TableRow 
                    key={index}
                    sx={{ 
                      '&:hover': { bgcolor: alpha(theme.palette.primary.main, 0.01) },
                    }}
                  >
                    <TableCell sx={{ py: 2 }}>
                      <Typography variant="body2" fontWeight={500}>
                        {item.description}
                      </Typography>
                    </TableCell>
                    <TableCell align="right" sx={{ py: 2 }}>{item.quantity}</TableCell>
                    <TableCell align="right" sx={{ py: 2 }}>₹{parseFloat(item.rate).toFixed(2)}</TableCell>
                    <TableCell align="right" sx={{ py: 2, fontWeight: 600 }}>₹{parseFloat(item.amount).toFixed(2)}</TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
          
          {/* Invoice totals */}
          <Box sx={{ 
            mt: 2, 
            p: 3, 
            display: 'flex', 
            flexDirection: 'column', 
            alignItems: 'flex-end',
            borderTop: `1px solid ${theme.palette.divider}`,
            bgcolor: alpha(theme.palette.primary.main, 0.02),
          }}>
            <Box sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              width: { xs: '100%', sm: '300px' },
              mb: 1
            }}>
              <Typography variant="body2" color="text.secondary">Subtotal:</Typography>
              <Typography variant="body1" fontWeight={500}>
                ₹{parseFloat(invoice.subtotal).toFixed(2)}
              </Typography>
            </Box>
            <Box sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              width: { xs: '100%', sm: '300px' },
              mb: 1
            }}>
              <Typography variant="body2" color="text.secondary">
                CGST ({getCgstRate()}%):
              </Typography>
              <Typography variant="body1" fontWeight={500}>
                ₹{getCgstAmount().toFixed(2)}
              </Typography>
            </Box>
            <Box sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              width: { xs: '100%', sm: '300px' },
              mb: 1
            }}>
              <Typography variant="body2" color="text.secondary">
                SGST ({getSgstRate()}%):
              </Typography>
              <Typography variant="body1" fontWeight={500}>
                ₹{getSgstAmount().toFixed(2)}
              </Typography>
            </Box>
            <Divider sx={{ width: { xs: '100%', sm: '300px' }, my: 1.5 }} />
            <Box sx={{ 
              display: 'flex', 
              justifyContent: 'space-between', 
              width: { xs: '100%', sm: '300px' },
              mb: 1
            }}>
              <Typography variant="subtitle1" fontWeight={600}>Total:</Typography>
              <Typography variant="h6" fontWeight={700} color="primary.main">
                ₹{parseFloat(invoice.total).toFixed(2)}
              </Typography>
            </Box>
          </Box>
        </CardContent>
      </Card>
      
      {/* Actions Card */}
      <Card sx={{ mb: 4, bgcolor: alpha(theme.palette.info.main, 0.05) }}>
        <CardContent sx={{ p: 3 }}>
          <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
            <MoneyIcon sx={{ color: theme.palette.info.main, mr: 1 }} />
            <Typography variant="h6" fontWeight={600}>
              Payment Information
            </Typography>
          </Box>
          <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
            This invoice has been issued and is awaiting payment. You can download the PDF to share with your client.
          </Typography>
          <Button
            variant="contained"
            color="info"
            startIcon={<DownloadIcon />}
            onClick={handleDownloadInvoice}
            sx={{ 
              mt: 1,
              boxShadow: '0px 4px 10px rgba(59, 130, 246, 0.2)',
              '&:hover': {
                boxShadow: '0px 6px 15px rgba(59, 130, 246, 0.3)',
              }
            }}
          >
            Download Invoice PDF
          </Button>
        </CardContent>
      </Card>
      
      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={handleCloseNotification} 
          severity={notification.severity}
          sx={{ 
            width: '100%',
            boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.15)',
            borderRadius: 2
          }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
} 