import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../contexts/AuthContext';
import axiosInstance from '../config/axiosConfig';
import './Clients.css';
import { Button, CircularProgress, Alert } from '@mui/material';
import AddIcon from '@mui/icons-material/Add';

const Clients = () => {
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const { user } = useAuth();
  const navigate = useNavigate();

  useEffect(() => {
    const fetchClients = async () => {
      try {
        setLoading(true);
        // Use the real API endpoint instead of mock data
        const response = await axiosInstance.get('/api/clients');
        setClients(response.data);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching clients:', err);
        setError('Failed to fetch clients. Please check the ClientProfiles page for complete functionality.');
        setLoading(false);
      }
    };

    fetchClients();
  }, [user]);

  if (loading) {
    return <div className="dashboard-content-container clients-loading">Loading clients...</div>;
  }

  if (error) {
    return (
      <div className="dashboard-content-container clients-error">
        <p>{error}</p>
        <Link to="/client-profiles" className="clients-link">
          Go to Client Profiles
        </Link>
      </div>
    );
  }

  // If no clients were loaded, suggest the client-profiles page
  if (clients.length === 0) {
    return (
      <div className="dashboard-content-container clients-page">
        <div className="clients-header">
          <div className="header-content">
            <div className="header-left">
              <h1>Clients</h1>
              <p>No clients found. For full functionality, please use the original client profiles page:</p>
            </div>
            <Link to="/client-profiles" className="create-client-btn">
              Go to Client Profiles
            </Link>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-content-container clients-page">
      <div className="clients-header">
        <div className="header-content">
          <div className="header-left">
            <h1>Clients</h1>
            <div className="client-stats">
              <div className="stat">
                <span className="stat-value">{clients.length}</span>
                <span className="stat-label">Total</span>
              </div>
            </div>
          </div>
          <Link to="/client-profiles" className="create-client-btn">Manage Clients</Link>
        </div>
      </div>

      <div className="clients-content">
        <div className="clients-grid">
          {clients.map(client => (
            <div key={client.id} className="client-card">
              <div className="client-info">
                <h2>{client.name}</h2>
                <div className="contact-person">
                  <span className="label">Contact:</span>
                  <span>{client.contactPerson}</span>
                </div>
                <div className="contact-details">
                  <div className="email">
                    <span className="label">Email:</span>
                    <a href={`mailto:${client.email}`}>{client.email}</a>
                  </div>
                  <div className="phone">
                    <span className="label">Phone:</span>
                    <a href={`tel:${client.phone}`}>{client.phone}</a>
                  </div>
                </div>
                <div className="address">
                  <span className="label">Address:</span>
                  <span>{client.address}</span>
                </div>
              </div>
              
              <div className="client-stats">
                <div className="stat">
                  <span className="stat-value">{client.activeProjects || 0}</span>
                  <span className="stat-label">Active Projects</span>
                </div>
                <div className="stat">
                  <span className="stat-value">{client.totalInvoices || 0}</span>
                  <span className="stat-label">Total Invoices</span>
                </div>
              </div>
              
              <div className="client-actions">
                <Link to={`/client-profiles?edit=${client.id}`} className="action-btn edit">Edit</Link>
                <Link to={`/client-profiles?view=${client.id}`} className="action-btn view">View Details</Link>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Clients; 