import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  Grid,
  TextField,
  Button,
  MenuItem,
  IconButton,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  CircularProgress,
  Avatar,
  Snackbar,
  Alert,
  Divider
} from '@mui/material';
import DeleteIcon from '@mui/icons-material/Delete';
import AddIcon from '@mui/icons-material/Add';
import DownloadIcon from '@mui/icons-material/Download';
import axiosInstance from '../config/axiosConfig';
import { useAuth } from '../contexts/AuthContext';
import { useNavigate } from 'react-router-dom';

export default function CreateInvoice() {
  const { user } = useAuth();
  const navigate = useNavigate();

  // Function to get current date in IST
  const getCurrentDateIST = () => {
    const now = new Date();
    const istOffset = 5.5 * 60 * 60 * 1000; // IST is UTC+5:30
    const istDate = new Date(now.getTime() + istOffset);
    const day = String(istDate.getUTCDate()).padStart(2, '0');
    const month = String(istDate.getUTCMonth() + 1).padStart(2, '0');
    const year = istDate.getUTCFullYear();
    return `${day}-${month}-${year}`;
  };

  const [invoiceData, setInvoiceData] = useState({
    company: '',
    client: '',
    invoiceNumber: '',
    date: getCurrentDateIST(),
    items: [
      {
        id: 1,
        description: '',
        quantity: '',
        rate: '',
        amount: 0,
      },
    ],
    subtotal: 0,
    gst: 0,
    gstRate: 18,
    cgst: 0,
    sgst: 0,
    cgstRate: 9,
    sgstRate: 9,
    total: 0,
  });

  const [companies, setCompanies] = useState([]);
  const [clients, setClients] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [selectedClient, setSelectedClient] = useState(null);
  const [submitting, setSubmitting] = useState(false);
  const [createdInvoice, setCreatedInvoice] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // Fetch companies and clients when component mounts
  useEffect(() => {
    fetchCompanies();
    fetchClients();
    fetchNextInvoiceNumber();
    // Set current date in IST
    setInvoiceData(prev => ({
      ...prev,
      date: getCurrentDateIST()
    }));
  }, [user]);

  const fetchCompanies = async () => {
    try {
      const response = await axiosInstance.get('/api/companies');
      setCompanies(response.data);
      setLoading(false);
    } catch (error) {
      console.error('Error fetching companies:', error);
      setError('Failed to fetch companies');
      setLoading(false);
    }
  };

  const fetchClients = async () => {
    try {
      const response = await axiosInstance.get('/api/clients');
      setClients(response.data);
    } catch (error) {
      console.error('Error fetching clients:', error);
      setError('Failed to fetch clients');
    }
  };

  const fetchNextInvoiceNumber = async () => {
    try {
      const response = await axiosInstance.get('/api/invoice-number');
      setInvoiceData(prev => ({
        ...prev,
        invoiceNumber: response.data.nextInvoiceNumber.toString()
      }));
    } catch (error) {
      console.error('Error fetching invoice number:', error);
      // Set default invoice number if fetch fails
      setInvoiceData(prev => ({
        ...prev,
        invoiceNumber: '1001'
      }));
    }
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    
    // Special handling for date field to convert between formats
    if (name === 'date') {
      // Convert from YYYY-MM-DD to DD-MM-YYYY when receiving from date picker
      const [year, month, day] = value.split('-');
      const formattedDate = `${day}-${month}-${year}`;
      setInvoiceData((prev) => ({
        ...prev,
        [name]: formattedDate,
      }));
    } else if (name === 'cgstRate' || name === 'sgstRate') {
      // Handle GST rate components change
      const cgstRate = name === 'cgstRate' ? Number(value) || 0 : invoiceData.cgstRate;
      const sgstRate = name === 'sgstRate' ? Number(value) || 0 : invoiceData.sgstRate;
      const gstRate = cgstRate + sgstRate;
      
      const subtotal = invoiceData.subtotal;
      const cgst = subtotal * (cgstRate / 100);
      const sgst = subtotal * (sgstRate / 100);
      const gst = cgst + sgst;
      const total = subtotal + gst;
      
      setInvoiceData((prev) => ({
        ...prev,
        [name]: Number(value) || 0,
        cgstRate,
        sgstRate,
        gstRate,
        cgst,
        sgst,
        gst,
        total,
      }));
    } else {
      setInvoiceData((prev) => ({
        ...prev,
        [name]: value,
      }));
    }

    // If company is selected, find and set the selected company data
    if (name === 'company') {
      const company = companies.find(c => c.id === value);
      setSelectedCompany(company);
    }

    // If client is selected, find and set the selected client data
    if (name === 'client') {
      const client = clients.find(c => c.id === value);
      setSelectedClient(client);
    }
  };

  const handleItemChange = (index, field, value) => {
    const newItems = [...invoiceData.items];
    newItems[index][field] = value;

    // Calculate amount only if both quantity and rate are numbers
    if (field === 'quantity' || field === 'rate') {
      const quantity = Number(newItems[index].quantity) || 0;
      const rate = Number(newItems[index].rate) || 0;
      newItems[index].amount = quantity * rate;
    }

    // Calculate totals
    const subtotal = newItems.reduce((sum, item) => sum + (item.amount || 0), 0);
    const cgst = subtotal * (invoiceData.cgstRate / 100);
    const sgst = subtotal * (invoiceData.sgstRate / 100);
    const gst = cgst + sgst;
    const total = subtotal + gst;

    setInvoiceData((prev) => ({
      ...prev,
      items: newItems,
      subtotal,
      cgst,
      sgst,
      gst,
      total,
    }));
  };

  const addItem = () => {
    setInvoiceData((prev) => ({
      ...prev,
      items: [
        ...prev.items,
        {
          id: prev.items.length + 1,
          description: '',
          quantity: '',
          rate: '',
          amount: 0,
        },
      ],
    }));
  };

  const removeItem = (index) => {
    const newItems = invoiceData.items.filter((_, i) => i !== index);
    setInvoiceData((prev) => ({
      ...prev,
      items: newItems,
    }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Validate form
    if (!invoiceData.company || !invoiceData.client) {
      setNotification({
        open: true,
        message: 'Please select a company and client',
        severity: 'error'
      });
      return;
    }

    if (invoiceData.items.some(item => !item.description || !item.quantity || !item.rate)) {
      setNotification({
        open: true,
        message: 'Please fill in all item details',
        severity: 'error'
      });
      return;
    }

    try {
      setSubmitting(true);
      console.log('Starting invoice submission process');
      
      // Prepare invoice data with company and client names
      const companyObj = companies.find(c => c.id === invoiceData.company);
      const clientObj = clients.find(c => c.id === invoiceData.client);
      
      const invoiceToSubmit = {
        ...invoiceData,
        companyName: companyObj?.name || '',
        clientName: clientObj?.name || '',
      };
      
      console.log('Submitting invoice data:', invoiceToSubmit);
      
      // Create invoice with detailed error logging
      try {
        const response = await axiosInstance.post('/api/invoices', invoiceToSubmit);
        console.log('Invoice creation response:', response);
        
        if (!response.data) {
          console.error('No data received in response');
          throw new Error('Server returned empty response');
        }
        
        // Increment invoice number for next time
        console.log('Incrementing invoice number');
        await axiosInstance.post('/api/invoice-number/increment');
        
        setCreatedInvoice(response.data);
        setNotification({
          open: true,
          message: 'Invoice created successfully!',
          severity: 'success'
        });
      } catch (apiError) {
        console.error('API error:', apiError);
        
        // Check if this is a network error
        if (apiError.message === 'Network Error') {
          throw new Error('Network connection error. Please check your internet connection and try again.');
        }
        
        // Re-throw the error for the outer catch block
        throw apiError;
      }
    } catch (error) {
      console.error('Error creating invoice:', error);
      
      let errorMessage = 'Failed to create invoice';
      
      if (error.message === 'Network Error') {
        errorMessage = 'Network connection error. Please check your internet connection and try again.';
      } else if (error.response) {
        console.error('Error response:', error.response.data);
        
        if (error.response.data.message) {
          errorMessage = error.response.data.message;
        } else if (error.response.data.error && typeof error.response.data.error === 'string') {
          errorMessage = error.response.data.error;
        } else if (error.response.status === 401) {
          errorMessage = 'Authentication error. Please log in again.';
        } else if (error.response.status === 500) {
          errorMessage = 'Server error: ' + (error.response.data.message || 'Unknown internal server error');
        }
        
        // If there's a specific database error
        if (error.response.data.error && error.response.data.error.details) {
          errorMessage += ' - ' + error.response.data.error.details;
        }
      } else if (error.request) {
        errorMessage = 'No response received from server. Please check your connection.';
      } else {
        errorMessage += ': ' + error.message;
      }
      
      console.error('Final error message:', errorMessage);
      
      setNotification({
        open: true,
        message: errorMessage,
        severity: 'error'
      });
    } finally {
      setSubmitting(false);
    }
  };

  const handleDownloadPDF = async () => {
    if (!createdInvoice) return;
    
    try {
      const response = await axiosInstance.get(`/api/invoices/${createdInvoice.id}/download`, {
        responseType: 'blob'
      });
      
      // Create a blob URL and trigger download
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `invoice-${createdInvoice.invoiceNumber}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
    } catch (error) {
      console.error('Error downloading invoice:', error);
      setNotification({
        open: true,
        message: 'Failed to download invoice',
        severity: 'error'
      });
    }
  };

  const resetForm = () => {
    setInvoiceData({
      company: '',
      client: '',
      invoiceNumber: '',
      date: getCurrentDateIST(),
      items: [
        {
          id: 1,
          description: '',
          quantity: '',
          rate: '',
          amount: 0,
        },
      ],
      subtotal: 0,
      gst: 0,
      gstRate: 18,
      cgst: 0,
      sgst: 0,
      cgstRate: 9,
      sgstRate: 9,
      total: 0,
    });
    setSelectedCompany(null);
    setSelectedClient(null);
    fetchNextInvoiceNumber();
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({
      ...prev,
      open: false
    }));
  };

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', mt: 4 }}>
        <CircularProgress />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ mt: 4 }}>
        <Typography color="error">{error}</Typography>
      </Box>
    );
  }

  return (
    <Box>
      <Typography variant="h4" sx={{ mb: 3 }}>
        Create Invoice
      </Typography>

      <Paper sx={{ p: 3 }}>
        <form onSubmit={handleSubmit}>
          <Grid container spacing={3}>
            <Grid item xs={12} sm={6}>
              <TextField
                select
                fullWidth
                label="Select Company"
                name="company"
                value={invoiceData.company}
                onChange={handleChange}
                required
                SelectProps={{
                  renderValue: (selected) => {
                    const selectedCompany = companies.find(c => c.id === selected);
                    if (!selectedCompany) return '';
                    
                    return (
                      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                        {selectedCompany.logo_url ? (
                          <Box
                            component="img"
                            src={selectedCompany.logo_url}
                            alt={selectedCompany.name}
                            sx={{
                              width: 28,
                              height: 28,
                              objectFit: 'contain',
                              borderRadius: 0.5,
                            }}
                          />
                        ) : (
                          <Avatar sx={{ width: 28, height: 28 }} variant="rounded">
                            {selectedCompany.name.charAt(0)}
                          </Avatar>
                        )}
                        <Typography variant="body1" noWrap>
                          {selectedCompany.name}
                        </Typography>
                      </Box>
                    );
                  },
                  MenuProps: {
                    PaperProps: {
                      style: {
                        maxHeight: 400,
                      },
                    },
                  },
                }}
              >
                {companies.map((company) => (
                  <MenuItem key={company.id} value={company.id} sx={{ py: 2, minHeight: 60 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2, width: '100%' }}>
                      {company.logo_url ? (
                        <Box
                          component="img"
                          src={company.logo_url}
                          alt={company.name}
                          sx={{
                            width: 50,
                            height: 50,
                            objectFit: 'contain',
                            borderRadius: 1,
                            backgroundColor: 'background.paper',
                            p: 0.5,
                            border: '1px solid',
                            borderColor: 'divider'
                          }}
                        />
                      ) : (
                        <Avatar
                          sx={{ width: 50, height: 50 }}
                          variant="rounded"
                        >
                          {company.name.charAt(0)}
                        </Avatar>
                      )}
                      <Typography>{company.name}</Typography>
                    </Box>
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                select
                fullWidth
                label="Select Client"
                name="client"
                value={invoiceData.client}
                onChange={handleChange}
                required
              >
                {clients.map((client) => (
                  <MenuItem key={client.id} value={client.id}>
                    {client.name} - {client.companyDetails}
                  </MenuItem>
                ))}
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Invoice Number"
                name="invoiceNumber"
                value={invoiceData.invoiceNumber}
                onChange={handleChange}
                required
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                type="date"
                label="Invoice Date"
                name="date"
                // Convert from DD-MM-YYYY to YYYY-MM-DD for date input
                value={invoiceData.date.split('-').reverse().join('-')}
                onChange={handleChange}
                InputLabelProps={{ shrink: true }}
                required
              />
            </Grid>
          </Grid>

          <Box sx={{ mt: 4 }}>
            <Box sx={{ display: 'flex', justifyContent: 'space-between', mb: 2 }}>
              <Typography variant="h6">Invoice Items</Typography>
              <Button
                startIcon={<AddIcon />}
                onClick={addItem}
              >
                Add Item
              </Button>
            </Box>

            <TableContainer>
              <Table>
                <TableHead>
                  <TableRow>
                    <TableCell>Description</TableCell>
                    <TableCell align="right" width="120px">Quantity</TableCell>
                    <TableCell align="right" width="120px">Rate</TableCell>
                    <TableCell align="right" width="120px">Amount</TableCell>
                    <TableCell align="right" width="80px">Action</TableCell>
                  </TableRow>
                </TableHead>
                <TableBody>
                  {invoiceData.items.map((item, index) => (
                    <TableRow key={item.id}>
                      <TableCell>
                        <TextField
                          fullWidth
                          value={item.description}
                          onChange={(e) =>
                            handleItemChange(index, 'description', e.target.value)
                          }
                          placeholder="Item description"
                        />
                      </TableCell>
                      <TableCell align="right" width="120px">
                        <TextField
                          type="number"
                          value={item.quantity}
                          onChange={(e) => {
                            const value = e.target.value === '' ? '' : Number(e.target.value);
                            handleItemChange(index, 'quantity', value);
                          }}
                          sx={{ width: 100 }}
                          inputProps={{
                            min: 0,
                            step: 1
                          }}
                          placeholder="0"
                          InputLabelProps={{ shrink: true }}
                        />
                      </TableCell>
                      <TableCell align="right" width="120px">
                        <TextField
                          type="number"
                          value={item.rate}
                          onChange={(e) => {
                            const value = e.target.value === '' ? '' : Number(e.target.value);
                            handleItemChange(index, 'rate', value);
                          }}
                          sx={{ width: 100 }}
                          inputProps={{
                            min: 0,
                            step: 1
                          }}
                          placeholder="0"
                          InputLabelProps={{ shrink: true }}
                        />
                      </TableCell>
                      <TableCell align="right" width="120px">
                        ₹{item.amount.toFixed(2)}
                      </TableCell>
                      <TableCell align="right" width="80px">
                        <IconButton
                          color="error"
                          onClick={() => removeItem(index)}
                          disabled={invoiceData.items.length === 1}
                        >
                          <DeleteIcon />
                        </IconButton>
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Box sx={{ mt: 3, display: 'flex', flexDirection: 'column', alignItems: 'flex-end' }}>
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                width: '100%', 
                maxWidth: 400,
                mb: 2 
              }}>
                <Typography variant="subtitle2" color="text.secondary">Subtotal:</Typography>
                <Typography variant="subtitle1" fontWeight={500}>
                  ₹{invoiceData.subtotal.toFixed(2)}
                </Typography>
              </Box>
              
              {/* CGST Row */}
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                width: '100%', 
                maxWidth: 400,
                mb: 1.5 
              }}>
                <Box sx={{ display: 'flex', alignItems: 'center', width: '60%' }}>
                  <Typography variant="subtitle2" color="text.secondary" sx={{ mr: 1, width: '40%' }}>CGST Rate:</Typography>
                  <TextField
                    type="number"
                    name="cgstRate"
                    value={invoiceData.cgstRate}
                    onChange={handleChange}
                    sx={{ width: '30%' }}
                    inputProps={{
                      min: 0,
                      max: 50,
                      step: 0.1
                    }}
                    size="small"
                  />
                  <Typography sx={{ ml: 1 }}>%</Typography>
                </Box>
                <Typography variant="subtitle1" fontWeight={500}>
                  ₹{invoiceData.cgst.toFixed(2)}
                </Typography>
              </Box>
              
              {/* SGST Row */}
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                alignItems: 'center',
                width: '100%', 
                maxWidth: 400,
                mb: 2 
              }}>
                <Box sx={{ display: 'flex', alignItems: 'center', width: '60%' }}>
                  <Typography variant="subtitle2" color="text.secondary" sx={{ mr: 1, width: '40%' }}>SGST Rate:</Typography>
                  <TextField
                    type="number"
                    name="sgstRate"
                    value={invoiceData.sgstRate}
                    onChange={handleChange}
                    sx={{ width: '30%' }}
                    inputProps={{
                      min: 0,
                      max: 50,
                      step: 0.1
                    }}
                    size="small"
                  />
                  <Typography sx={{ ml: 1 }}>%</Typography>
                </Box>
                <Typography variant="subtitle1" fontWeight={500}>
                  ₹{invoiceData.sgst.toFixed(2)}
                </Typography>
              </Box>
              
              <Divider sx={{ width: '100%', maxWidth: 400, mb: 2 }} />
              
              <Box sx={{ 
                display: 'flex', 
                justifyContent: 'space-between', 
                width: '100%', 
                maxWidth: 400
              }}>
                <Typography variant="subtitle1" fontWeight={600}>Total:</Typography>
                <Typography variant="h6" fontWeight={700} color="primary.main">
                  ₹{invoiceData.total.toFixed(2)}
                </Typography>
              </Box>
            </Box>
          </Box>

          <Box sx={{ mt: 4, display: 'flex', justifyContent: 'space-between' }}>
            <Button
              variant="outlined"
              onClick={resetForm}
              disabled={submitting}
            >
              Reset
            </Button>
            
            <Box>
              {createdInvoice && (
                <Button
                  variant="outlined"
                  startIcon={<DownloadIcon />}
                  onClick={handleDownloadPDF}
                  sx={{ mr: 2 }}
                >
                  Download PDF
                </Button>
              )}
              
              <Button
                type="submit"
                variant="contained"
                disabled={submitting}
              >
                {submitting ? 'Creating...' : 'Create Invoice'}
              </Button>
            </Box>
          </Box>
        </form>
      </Paper>
      
      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={handleCloseNotification} 
          severity={notification.severity}
          sx={{ width: '100%' }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
} 