import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Button,
  Chip,
  IconButton,
  TextField,
  InputAdornment,
  CircularProgress,
  Alert,
  Snackbar,
  Card,
  CardContent,
  Grid,
  Divider,
  Tooltip,
  useTheme,
  alpha,
} from '@mui/material';
import {
  Add as AddIcon,
  Search as SearchIcon,
  Visibility as ViewIcon,
  GetApp as DownloadIcon,
  Delete as DeleteIcon,
  Receipt as ReceiptIcon,
} from '@mui/icons-material';
import { useNavigate } from 'react-router-dom';
import axiosInstance from '../config/axiosConfig';
import { useAuth } from '../contexts/AuthContext';

export default function AllInvoices() {
  const navigate = useNavigate();
  const { user } = useAuth();
  const theme = useTheme();
  const [searchTerm, setSearchTerm] = useState('');
  const [invoices, setInvoices] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [notification, setNotification] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  // Fetch invoices when component mounts
  useEffect(() => {
    fetchInvoices();
  }, [user]);

  const fetchInvoices = async () => {
    try {
      setLoading(true);
      const response = await axiosInstance.get('/api/invoices');
      setInvoices(response.data);
      setError(null);
    } catch (error) {
      console.error('Error fetching invoices:', error);
      setError('Failed to fetch invoices. Please try again later.');
    } finally {
      setLoading(false);
    }
  };

  const handleDownloadInvoice = async (invoiceId, invoiceNumber) => {
    try {
      const response = await axiosInstance.get(`/api/invoices/${invoiceId}/download`, {
        responseType: 'blob'
      });
      
      // Create a blob URL and trigger download
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', `invoice-${invoiceNumber}.pdf`);
      document.body.appendChild(link);
      link.click();
      link.remove();
      
      setNotification({
        open: true,
        message: 'Invoice downloaded successfully!',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error downloading invoice:', error);
      setNotification({
        open: true,
        message: 'Failed to download invoice',
        severity: 'error'
      });
    }
  };

  const handleViewInvoice = (invoiceId) => {
    navigate(`/invoices/${invoiceId}`);
  };

  const getStatusColor = (status) => {
    switch (status) {
      case 'Paid':
        return 'success';
      case 'Pending':
        return 'warning';
      case 'Overdue':
        return 'error';
      default:
        return 'default';
    }
  };

  const handleSearch = (event) => {
    setSearchTerm(event.target.value);
  };

  const handleCloseNotification = () => {
    setNotification(prev => ({
      ...prev,
      open: false
    }));
  };

  const filteredInvoices = invoices.filter((invoice) =>
    Object.values(invoice).some(
      (value) =>
        value &&
        value.toString().toLowerCase().includes(searchTerm.toLowerCase())
    )
  );

  // Format date from ISO string to local date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    
    try {
      // Handle both ISO dates and DD-MM-YYYY format
      let date;
      if (dateString.includes('-') && dateString.includes('T')) {
        // ISO format
        date = new Date(dateString);
      } else if (dateString.includes('-') && dateString.split('-').length === 3) {
        // DD-MM-YYYY format
        const [day, month, year] = dateString.split('-');
        date = new Date(year, month - 1, day);
      } else {
        return dateString; // Return as is if format is unknown
      }
      
      return date.toLocaleDateString();
    } catch (error) {
      console.error('Error formatting date:', error);
      return dateString; // Return original string if there's an error
    }
  };

  // Calculate summary statistics
  const calculateSummary = () => {
    if (!invoices.length) return { total: 0, count: 0, average: 0 };
    
    const total = invoices.reduce((sum, invoice) => sum + parseFloat(invoice.total || 0), 0);
    return {
      total,
      count: invoices.length,
      average: total / invoices.length
    };
  };

  const summary = calculateSummary();

  if (loading) {
    return (
      <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '70vh' }}>
        <CircularProgress size={60} thickness={4} />
      </Box>
    );
  }

  if (error) {
    return (
      <Box sx={{ mt: 4, p: 3, textAlign: 'center' }}>
        <Alert 
          severity="error" 
          sx={{ 
            mb: 3, 
            maxWidth: 600, 
            mx: 'auto',
            '& .MuiAlert-icon': { fontSize: '2rem' }
          }}
        >
          {error}
        </Alert>
        <Button 
          variant="contained" 
          size="large"
          onClick={fetchInvoices}
          sx={{ mt: 2 }}
        >
          Retry
        </Button>
      </Box>
    );
  }

  return (
    <Box>
      <Box sx={{ mb: 4 }}>
        <Typography 
          variant="h4" 
          sx={{ 
            fontWeight: 700, 
            mb: 1,
            background: `linear-gradient(90deg, ${theme.palette.primary.main} 0%, ${theme.palette.secondary.main} 100%)`,
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
          }}
        >
          Invoices
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
          Manage and track all your invoices in one place
        </Typography>
      </Box>

      {/* Summary Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={4}>
          <Card sx={{ 
            height: '100%', 
            background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.1)} 0%, ${alpha(theme.palette.primary.light, 0.1)} 100%)`,
            border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Box sx={{ 
                  p: 1.5, 
                  borderRadius: '12px', 
                  bgcolor: alpha(theme.palette.primary.main, 0.1),
                  color: theme.palette.primary.main,
                  mr: 2
                }}>
                  <ReceiptIcon />
                </Box>
                <Typography variant="h6" color="text.secondary">Total Invoices</Typography>
              </Box>
              <Typography variant="h3" sx={{ fontWeight: 700, mb: 1 }}>
                {summary.count}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                All invoices in your account
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card sx={{ 
            height: '100%',
            background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.1)} 0%, ${alpha(theme.palette.success.light, 0.1)} 100%)`,
            border: `1px solid ${alpha(theme.palette.success.main, 0.1)}`,
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Box sx={{ 
                  p: 1.5, 
                  borderRadius: '12px', 
                  bgcolor: alpha(theme.palette.success.main, 0.1),
                  color: theme.palette.success.main,
                  mr: 2
                }}>
                  <ReceiptIcon />
                </Box>
                <Typography variant="h6" color="text.secondary">Total Amount</Typography>
              </Box>
              <Typography variant="h3" sx={{ fontWeight: 700, mb: 1 }}>
                ₹{summary.total.toFixed(2)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Sum of all invoice amounts
              </Typography>
            </CardContent>
          </Card>
        </Grid>
        <Grid item xs={12} sm={4}>
          <Card sx={{ 
            height: '100%',
            background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.1)} 0%, ${alpha(theme.palette.info.light, 0.1)} 100%)`,
            border: `1px solid ${alpha(theme.palette.info.main, 0.1)}`,
          }}>
            <CardContent sx={{ p: 3 }}>
              <Box sx={{ display: 'flex', alignItems: 'center', mb: 2 }}>
                <Box sx={{ 
                  p: 1.5, 
                  borderRadius: '12px', 
                  bgcolor: alpha(theme.palette.info.main, 0.1),
                  color: theme.palette.info.main,
                  mr: 2
                }}>
                  <ReceiptIcon />
                </Box>
                <Typography variant="h6" color="text.secondary">Average Amount</Typography>
              </Box>
              <Typography variant="h3" sx={{ fontWeight: 700, mb: 1 }}>
                ₹{summary.average.toFixed(2)}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Average invoice value
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      <Box sx={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', mb: 3 }}>
        <Typography variant="h5" sx={{ fontWeight: 600 }}>All Invoices</Typography>
        <Button
          variant="contained"
          startIcon={<AddIcon />}
          onClick={() => navigate('/create-invoice')}
          sx={{ 
            px: 3, 
            py: 1.2,
            boxShadow: '0px 4px 10px rgba(37, 99, 235, 0.2)',
            '&:hover': {
              boxShadow: '0px 6px 15px rgba(37, 99, 235, 0.3)',
            }
          }}
        >
          Create Invoice
        </Button>
      </Box>

      <Paper sx={{ p: 3, mb: 4, overflow: 'hidden' }}>
        <Box sx={{ mb: 3 }}>
          <TextField
            fullWidth
            variant="outlined"
            placeholder="Search invoices by number, company, client..."
            value={searchTerm}
            onChange={handleSearch}
            InputProps={{
              startAdornment: (
                <InputAdornment position="start">
                  <SearchIcon color="action" />
                </InputAdornment>
              ),
              sx: { 
                borderRadius: 2,
                bgcolor: alpha(theme.palette.common.black, 0.02),
                '&:hover': {
                  bgcolor: alpha(theme.palette.common.black, 0.03),
                },
                '& .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'transparent'
                },
                '&:hover .MuiOutlinedInput-notchedOutline': {
                  borderColor: 'transparent'
                },
                '&.Mui-focused .MuiOutlinedInput-notchedOutline': {
                  borderColor: theme.palette.primary.main,
                  borderWidth: '1px'
                }
              }
            }}
          />
        </Box>

        <TableContainer sx={{ 
          borderRadius: 2,
          boxShadow: 'none',
          border: `1px solid ${theme.palette.divider}`,
          overflow: 'hidden'
        }}>
          <Table>
            <TableHead>
              <TableRow sx={{ bgcolor: alpha(theme.palette.primary.main, 0.03) }}>
                <TableCell sx={{ fontWeight: 600, py: 2 }}>Invoice Number</TableCell>
                <TableCell sx={{ fontWeight: 600, py: 2 }}>Date</TableCell>
                <TableCell sx={{ fontWeight: 600, py: 2 }}>Company</TableCell>
                <TableCell sx={{ fontWeight: 600, py: 2 }}>Client</TableCell>
                <TableCell align="right" sx={{ fontWeight: 600, py: 2 }}>Amount</TableCell>
                <TableCell align="right" sx={{ fontWeight: 600, py: 2 }}>Actions</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {filteredInvoices.map((invoice) => (
                <TableRow 
                  key={invoice.id}
                  sx={{ 
                    '&:hover': { 
                      bgcolor: alpha(theme.palette.primary.main, 0.02),
                      cursor: 'pointer'
                    },
                    transition: 'background-color 0.2s'
                  }}
                  onClick={() => handleViewInvoice(invoice.id)}
                >
                  <TableCell sx={{ py: 2 }}>
                    <Box sx={{ display: 'flex', alignItems: 'center' }}>
                      <Box 
                        sx={{ 
                          width: 32, 
                          height: 32, 
                          borderRadius: '8px', 
                          bgcolor: alpha(theme.palette.primary.main, 0.1),
                          color: theme.palette.primary.main,
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          mr: 2
                        }}
                      >
                        <ReceiptIcon fontSize="small" />
                      </Box>
                      <Typography variant="body2" fontWeight={500}>
                        {invoice.invoice_number}
                      </Typography>
                    </Box>
                  </TableCell>
                  <TableCell sx={{ py: 2 }}>{formatDate(invoice.date)}</TableCell>
                  <TableCell sx={{ py: 2 }}>{invoice.company_name}</TableCell>
                  <TableCell sx={{ py: 2 }}>{invoice.client_name}</TableCell>
                  <TableCell align="right" sx={{ py: 2, fontWeight: 600 }}>
                    ₹{parseFloat(invoice.total).toFixed(2)}
                  </TableCell>
                  <TableCell align="right" sx={{ py: 2 }} onClick={(e) => e.stopPropagation()}>
                    <Tooltip title="View Invoice">
                      <IconButton
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleViewInvoice(invoice.id);
                        }}
                        sx={{ 
                          color: theme.palette.primary.main,
                          bgcolor: alpha(theme.palette.primary.main, 0.1),
                          mr: 1,
                          '&:hover': {
                            bgcolor: alpha(theme.palette.primary.main, 0.2),
                          }
                        }}
                      >
                        <ViewIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                    <Tooltip title="Download Invoice">
                      <IconButton
                        size="small"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDownloadInvoice(invoice.id, invoice.invoice_number);
                        }}
                        sx={{ 
                          color: theme.palette.success.main,
                          bgcolor: alpha(theme.palette.success.main, 0.1),
                          '&:hover': {
                            bgcolor: alpha(theme.palette.success.main, 0.2),
                          }
                        }}
                      >
                        <DownloadIcon fontSize="small" />
                      </IconButton>
                    </Tooltip>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>

        {filteredInvoices.length === 0 && (
          <Box sx={{ 
            textAlign: 'center', 
            py: 6,
            px: 2,
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center'
          }}>
            <Box 
              sx={{ 
                width: 80, 
                height: 80, 
                borderRadius: '50%', 
                bgcolor: alpha(theme.palette.primary.main, 0.1),
                color: theme.palette.primary.main,
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                mb: 2
              }}
            >
              <ReceiptIcon sx={{ fontSize: 40 }} />
            </Box>
            <Typography variant="h6" color="text.primary" sx={{ mb: 1 }}>
              No invoices found
            </Typography>
            <Typography color="text.secondary" sx={{ maxWidth: 400, mx: 'auto', mb: 3 }}>
              {searchTerm ? 
                `No invoices match your search criteria "${searchTerm}". Try a different search term or clear the search.` : 
                "You haven't created any invoices yet. Click the 'Create Invoice' button to get started."}
            </Typography>
            {searchTerm ? (
              <Button 
                variant="outlined" 
                onClick={() => setSearchTerm('')}
              >
                Clear Search
              </Button>
            ) : (
              <Button 
                variant="contained" 
                startIcon={<AddIcon />}
                onClick={() => navigate('/create-invoice')}
              >
                Create Your First Invoice
              </Button>
            )}
          </Box>
        )}
      </Paper>
      
      {/* Notification */}
      <Snackbar
        open={notification.open}
        autoHideDuration={6000}
        onClose={handleCloseNotification}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert 
          onClose={handleCloseNotification} 
          severity={notification.severity}
          sx={{ 
            width: '100%',
            boxShadow: '0px 4px 12px rgba(0, 0, 0, 0.15)',
            borderRadius: 2
          }}
        >
          {notification.message}
        </Alert>
      </Snackbar>
    </Box>
  );
} 