import React, { useState, useEffect, useRef } from 'react';
import {
  Container,
  Box,
  Typography,
  Paper,
  TextField,
  Button,
  Avatar,
  Grid,
  Divider,
  IconButton,
  Alert,
  Snackbar,
  useTheme,
  CircularProgress,
  Badge,
  useMediaQuery
} from '@mui/material';
import EditIcon from '@mui/icons-material/Edit';
import PhotoCameraIcon from '@mui/icons-material/PhotoCamera';
import { useAuth } from '../contexts/AuthContext';
import { supabase } from '../config/supabaseClient';

const Profile = () => {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const { user, updateProfile, uploadAvatar } = useAuth();
  const fileInputRef = useRef(null);
  
  const [isEditing, setIsEditing] = useState(false);
  const [isUploading, setIsUploading] = useState(false);
  const [profileData, setProfileData] = useState({
    fullName: '',
    email: '',
    phone: '',
    company: '',
    location: '',
    bio: '',
    avatarUrl: ''
  });
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });

  useEffect(() => {
    const fetchProfileData = async () => {
      if (user) {
        // Get user metadata from auth
        const fullName = user.user_metadata?.full_name || '';
        const avatarUrl = user.user_metadata?.avatar_url || '';
        
        // Get additional profile data from profiles table
        const { data, error } = await supabase
          .from('profiles')
          .select('*')
          .eq('id', user.id)
          .single();
          
        if (error) {
          console.error('Error fetching profile:', error);
          return;
        }
        
        setProfileData({
          fullName: fullName || data?.full_name || '',
          email: user.email || '',
          phone: data?.phone || '',
          company: data?.company || '',
          location: data?.location || '',
          bio: data?.bio || '',
          avatarUrl: avatarUrl || data?.avatar_url || ''
        });
      }
    };
    
    fetchProfileData();
  }, [user]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setProfileData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleEditToggle = () => {
    setIsEditing(!isEditing);
    if (!isEditing) {
      // Reset form data when entering edit mode
      if (user) {
        setProfileData(prev => ({
          ...prev,
          fullName: user.user_metadata?.full_name || prev.fullName,
          email: user.email || prev.email
        }));
      }
    }
  };

  const handleAvatarClick = () => {
    if (isEditing) {
      fileInputRef.current.click();
    }
  };

  const handleFileChange = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    
    try {
      setIsUploading(true);
      
      // Upload the file using the AuthContext function
      const { success, avatarUrl, error } = await uploadAvatar(file);
      
      if (!success) {
        throw new Error(error || 'Failed to upload avatar');
      }
      
      // Update profile data with new avatar URL
      setProfileData(prev => ({
        ...prev,
        avatarUrl
      }));
      
      setSnackbar({
        open: true,
        message: 'Profile picture uploaded successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error uploading avatar:', error);
      setSnackbar({
        open: true,
        message: error.message || 'Failed to upload profile picture',
        severity: 'error'
      });
    } finally {
      setIsUploading(false);
      // Clear the file input
      e.target.value = null;
    }
  };

  const handleSaveChanges = async () => {
    try {
      // Update profile using the AuthContext function
      const { success, error } = await updateProfile(profileData);
      
      if (!success) {
        throw new Error(error || 'Failed to update profile');
      }
      
      setIsEditing(false);
      setSnackbar({
        open: true,
        message: 'Profile updated successfully',
        severity: 'success'
      });
    } catch (error) {
      console.error('Error updating profile:', error);
      setSnackbar({
        open: true,
        message: error.message || 'Failed to update profile',
        severity: 'error'
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar(prev => ({
      ...prev,
      open: false
    }));
  };

  // Function to get initials from name
  const getInitials = (name) => {
    return name
      .split(' ')
      .map(part => part[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  // Add this function near other utility functions like getInitials
  const maskEmail = (email) => {
    if (!email) return '';
    const parts = email.split('@');
    if (parts.length !== 2) return email;
    
    const username = parts[0];
    const domain = parts[1];
    
    // Show first 3 characters of username, then asterisks
    const maskedUsername = username.length > 3 ? 
      `${username.substring(0, 3)}${'*'.repeat(Math.min(username.length - 3, 5))}` : 
      username;
    
    return `${maskedUsername}@${domain}`;
  };

  return (
    <Container maxWidth="lg" sx={{ mt: 4, mb: 4 }}>
      <Paper elevation={3} sx={{ p: 3, borderRadius: 2 }}>
        <Grid container spacing={3}>
          <Grid item xs={12}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
              <Typography variant="h4" component="h1" gutterBottom>
                My Profile
              </Typography>
              <Button
                variant={isEditing ? "outlined" : "contained"}
                color={isEditing ? "secondary" : "primary"}
                onClick={handleEditToggle}
                startIcon={<EditIcon />}
              >
                {isEditing ? "Cancel" : "Edit Profile"}
              </Button>
            </Box>
            <Divider sx={{ mb: 3 }} />
          </Grid>
          
          <Grid item xs={12} md={4} sx={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <input
              type="file"
              ref={fileInputRef}
              style={{ display: 'none' }}
              accept="image/*"
              onChange={handleFileChange}
            />
            <Badge
              overlap="circular"
              anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
              badgeContent={
                isEditing ? (
                  <IconButton
                    sx={{
                      bgcolor: 'primary.main',
                      color: 'white',
                      '&:hover': { bgcolor: 'primary.dark' },
                      width: 32,
                      height: 32
                    }}
                    onClick={handleAvatarClick}
                  >
                    <PhotoCameraIcon fontSize="small" />
                  </IconButton>
                ) : null
              }
            >
              {isUploading ? (
                <Box position="relative" display="inline-flex">
                  <Avatar
                    sx={{ width: 120, height: 120, bgcolor: 'primary.main', fontSize: '2.5rem' }}
                  >
                    {getInitials(profileData.fullName)}
                  </Avatar>
                  <CircularProgress
                    size={120}
                    thickness={2}
                    sx={{
                      position: 'absolute',
                      top: 0,
                      left: 0,
                      zIndex: 1,
                      color: 'primary.light'
                    }}
                  />
                </Box>
              ) : (
                <Avatar
                  src={profileData.avatarUrl}
                  sx={{ 
                    width: 120, 
                    height: 120, 
                    bgcolor: 'primary.main', 
                    fontSize: '2.5rem',
                    cursor: isEditing ? 'pointer' : 'default'
                  }}
                  onClick={handleAvatarClick}
                >
                  {!profileData.avatarUrl && getInitials(profileData.fullName)}
                </Avatar>
              )}
            </Badge>
            
            <Typography variant="h6" sx={{ mt: 2, textAlign: 'center' }}>
              {profileData.fullName}
            </Typography>
          </Grid>
          
          <Grid item xs={12} md={8}>
            <Grid container spacing={2}>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Full Name"
                  name="fullName"
                  value={profileData.fullName}
                  onChange={handleInputChange}
                  disabled={!isEditing}
                  variant={isEditing ? "outlined" : "filled"}
                  margin="normal"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Email"
                  name="email"
                  value={profileData.email}
                  disabled
                  variant="filled"
                  margin="normal"
                  helperText="Email cannot be changed"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Phone"
                  name="phone"
                  value={profileData.phone}
                  onChange={handleInputChange}
                  disabled={!isEditing}
                  variant={isEditing ? "outlined" : "filled"}
                  margin="normal"
                />
              </Grid>
              <Grid item xs={12} sm={6}>
                <TextField
                  fullWidth
                  label="Company"
                  name="company"
                  value={profileData.company}
                  onChange={handleInputChange}
                  disabled={!isEditing}
                  variant={isEditing ? "outlined" : "filled"}
                  margin="normal"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Location"
                  name="location"
                  value={profileData.location}
                  onChange={handleInputChange}
                  disabled={!isEditing}
                  variant={isEditing ? "outlined" : "filled"}
                  margin="normal"
                />
              </Grid>
              <Grid item xs={12}>
                <TextField
                  fullWidth
                  label="Bio"
                  name="bio"
                  value={profileData.bio}
                  onChange={handleInputChange}
                  disabled={!isEditing}
                  variant={isEditing ? "outlined" : "filled"}
                  margin="normal"
                  multiline
                  rows={4}
                />
              </Grid>
            </Grid>
          </Grid>
          
          {isEditing && (
            <Grid item xs={12}>
              <Box display="flex" justifyContent="flex-end" mt={2}>
                <Button
                  variant="contained"
                  color="primary"
                  onClick={handleSaveChanges}
                  sx={{ ml: 2 }}
                >
                  Save Changes
                </Button>
              </Box>
            </Grid>
          )}
        </Grid>
      </Paper>
      
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Container>
  );
};

export default Profile; 