import React, { useState, useEffect } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import {
  Box,
  Grid,
  Paper,
  Typography,
  Card,
  CardContent,
  Button,
  Divider,
  CircularProgress,
  Alert,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Chip,
  useTheme,
  alpha,
  IconButton,
  Tooltip,
  Snackbar,
} from '@mui/material';
import {
  Assignment as ProjectsIcon,
  Receipt as InvoiceIcon,
  Business as CompanyIcon,
  Person as ClientIcon,
  AttachMoney as MoneyIcon,
  Add as AddIcon,
  Visibility as ViewIcon,
  GetApp as DownloadIcon,
  ArrowForward as ArrowForwardIcon,
  TrendingUp as TrendingUpIcon,
  Refresh as RefreshIcon,
  BugReport as DebugIcon,
  Notifications as NotificationsIcon,
  CalendarToday as CalendarIcon,
  VisibilityOutlined as ViewOutlinedIcon,
  Edit as EditIcon,
} from '@mui/icons-material';
import { useAuth, axiosInstance } from '../contexts/AuthContext';
import { useNotifications } from '../contexts/NotificationContext';
import { supabase } from '../config/supabaseClient';
import DirectBlogLink from '../components/common/DirectBlogLink';
import AddClientForm from '../components/client/AddClientForm';
import AddCompanyForm from '../components/company/AddCompanyForm';
import AddProjectForm from '../components/projects/AddProjectForm';
import './Dashboard.css';

const StatCard = ({ title, value, icon, className, subtitle, onClick }) => {
  const theme = useTheme();
  
  return (
    <div className={`stat-card ${className}`} onClick={onClick}>
      <div className="stat-card-icon">
        {icon}
      </div>
      <div className="stat-card-title">{title}</div>
      <div className="stat-card-value">{value}</div>
        {subtitle && (
        <div className="stat-card-subtitle">
            {subtitle}
          {onClick && <ArrowForwardIcon />}
        </div>
        )}
    </div>
);
};

export default function Dashboard() {
  const navigate = useNavigate();
  const { user, session, loading: authLoading } = useAuth();
  const { addNotification } = useNotifications();
  const theme = useTheme();
  const [stats, setStats] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [retryCount, setRetryCount] = useState(0);
  const [debugInfo, setDebugInfo] = useState(null);
  
  // State for form dialogs
  const [isAddClientDialogOpen, setIsAddClientDialogOpen] = useState(false);
  const [isAddCompanyDialogOpen, setIsAddCompanyDialogOpen] = useState(false);
  const [isAddProjectDialogOpen, setIsAddProjectDialogOpen] = useState(false);
  const [snackbar, setSnackbar] = useState({ open: false, message: '', severity: 'success' });

  // Check authentication before loading content
  useEffect(() => {
    console.log('Dashboard auth state:', { user: !!user, session: !!session, authLoading });
    
    if (!authLoading) {
      if (user && session) {
        console.log('User is authenticated, fetching dashboard data');
        console.log('Auth token:', session.access_token);
        fetchDashboardStats();
      } else {
        console.log('User is not authenticated, redirecting to login');
        navigate('/login');
      }
    }
  }, [user, session, authLoading, retryCount]);

  const fetchDashboardStats = async () => {
    try {
      setLoading(true);
      console.log('Fetching dashboard stats with token:', session?.access_token ? 'Token exists' : 'No token');
      
      // First check if backend API is available
      try {
        const healthCheck = await axiosInstance.get('/api/health');
        console.log('API health check:', healthCheck.data);
      } catch (healthError) {
        console.error('API health check failed:', healthError);
        throw new Error('Backend server connection failed. Please ensure the server is running.');
      }
      
      const response = await axiosInstance.get('/api/dashboard/stats');
      
      // Check if the response has the new format with success and data properties
      if (response.data && response.data.success === true && response.data.data) {
        setStats(response.data.data);
      } else if (response.data) {
        // Handle old format for backward compatibility
        setStats(response.data);
      } else {
        throw new Error('Invalid response format');
      }
      
      setError(null);
    } catch (error) {
      console.error('Error fetching dashboard stats:', error);
      
      // Extract the error message from the response if available
      let errorMessage = 'Failed to fetch dashboard statistics.';
      
      if (error.message && error.message.includes('server connection failed')) {
        errorMessage = 'Backend server connection failed. Please ensure the server is running.';
      } else if (error.response?.data?.error) {
        errorMessage = error.response.data.error;
      } else if (error.response?.status === 401) {
        errorMessage = 'Authentication error. Please log in again.';
      }
      
      setError(errorMessage);
      
      // Collect debug information for troubleshooting
      const debugInfo = {
        auth: {
          user: {
            id: user?.id,
            email: user?.email,
            isAuthenticated: !!user
          },
          session: {
            exists: !!session,
            hasToken: !!session?.access_token,
            tokenPreview: session?.access_token ? `${session.access_token.substring(0, 10)}...` : null,
            expiresAt: session?.expires_at
          },
          currentSession: {
            exists: !!session,
            hasToken: !!session?.access_token,
            tokenPreview: session?.access_token ? `${session.access_token.substring(0, 10)}...` : null,
            expiresAt: session?.expires_at
          }
        },
        api: {
          response: null,
          error: errorMessage
        },
        browser: {
          userAgent: navigator.userAgent,
          language: navigator.language
        },
        timestamp: new Date().toISOString()
      };
      
      setDebugInfo(debugInfo);
    } finally {
      setLoading(false);
    }
  };

  const handleRetry = () => {
    setRetryCount(prevCount => prevCount + 1);
  };

  const handleDebug = () => {
    // Collect debug information
    const debugInfo = {
      auth: {
        user: {
          id: user?.id,
          email: user?.email,
          isAuthenticated: !!user
        },
        session: {
          exists: !!session,
          hasToken: !!session?.access_token,
          tokenPreview: session?.access_token ? `${session.access_token.substring(0, 10)}...` : null,
          expiresAt: session?.expires_at
        },
        currentSession: {
          exists: !!session,
          hasToken: !!session?.access_token,
          tokenPreview: session?.access_token ? `${session.access_token.substring(0, 10)}...` : null,
          expiresAt: session?.expires_at
        }
      },
      api: {
        response: null,
        error: error || null
      },
      browser: {
        userAgent: navigator.userAgent,
        language: navigator.language
      },
      timestamp: new Date().toISOString()
    };
    
    setDebugInfo(debugInfo);
    console.log('Debug information:', debugInfo);
  };

  // Format currency
  const formatCurrency = (amount) => {
    return new Intl.NumberFormat('en-IN', {
      style: 'currency',
      currency: 'INR',
      maximumFractionDigits: 0,
    }).format(amount || 0);
  };

  // Format date
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    
    try {
      // Handle both ISO dates and DD-MM-YYYY format
      let date;
      if (dateString.includes('-') && dateString.includes('T')) {
        // ISO format
        date = new Date(dateString);
      } else if (dateString.includes('-') && dateString.split('-').length === 3) {
        // DD-MM-YYYY format
        const [day, month, year] = dateString.split('-');
        date = new Date(year, month - 1, day);
      } else {
        return dateString; // Return as is if format is unknown
      }
      
      return date.toLocaleDateString();
    } catch (error) {
      console.error('Error formatting date:', error);
      return dateString; // Return original string if there's an error
    }
  };

  // Get status color
  const getStatusColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'completed':
        return theme.palette.success.main;
      case 'in progress':
        return theme.palette.info.main;
      case 'pending':
        return theme.palette.warning.main;
      default:
        return theme.palette.grey[500];
    }
  };

  // Function to create a test notification
  const handleAddTestNotification = () => {
    const notificationTypes = ['success', 'info', 'warning', 'error'];
    const randomType = notificationTypes[Math.floor(Math.random() * notificationTypes.length)];
    
    const notifications = {
      success: {
        title: 'Payment Received',
        message: 'You have received a payment of ₹25,000 for invoice #INV-2023-005',
        type: 'success',
        link: '/invoices'
      },
      info: {
        title: 'New Comment',
        message: 'A team member added a comment to Project XYZ',
        type: 'info',
        link: '/projects'
      },
      warning: {
        title: 'Invoice Due Soon',
        message: 'Invoice #INV-2023-006 is due in 3 days',
        type: 'warning',
        link: '/invoices'
      },
      error: {
        title: 'Payment Failed',
        message: 'Payment processing failed for invoice #INV-2023-007',
        type: 'error',
        link: '/invoices'
      }
    };
    
    addNotification(notifications[randomType]);
  };

  // Handler functions for forms
  const handleAddClient = async (clientData) => {
    try {
      console.log('Adding client with data:', clientData);
      
      // Format the client data
      const formattedData = {
        name: clientData.name,
        companyDetails: clientData.companyDetails,
        hasGst: clientData.hasGst,
        gstNumber: clientData.hasGst === 'yes' ? clientData.gstNumber : null
      };

      const response = await axiosInstance.post('/api/clients', formattedData);
      console.log('Client created successfully:', response.data);

      setSnackbar({
        open: true,
        message: 'Client added successfully',
        severity: 'success'
      });
      
      // Refresh dashboard stats
      fetchDashboardStats();
    } catch (error) {
      console.error('Error adding client:', error.response?.data || error);
      setSnackbar({
        open: true,
        message: error.response?.data?.message || 'Failed to add client',
        severity: 'error'
      });
    }
  };

  const handleAddCompany = async (newCompany) => {
    try {
      console.log('Adding company with data:', newCompany);
      
      const formData = new FormData();
      
      // Append basic company information
      formData.append('name', newCompany.name || '');
      formData.append('address', newCompany.address || '');
      formData.append('email', newCompany.email || '');
      formData.append('phone', newCompany.phone || '');
      formData.append('gst', newCompany.gst || '');
      
      // Handle bank details properly
      const bankDetails = {
        accountName: newCompany.bankDetails.accountName || '',
        accountNumber: newCompany.bankDetails.accountNumber || '',
        bankName: newCompany.bankDetails.bankName || '',
        ifscCode: newCompany.bankDetails.ifscCode || '',
        branch: newCompany.bankDetails.branch || ''
      };
      formData.append('bankDetails', JSON.stringify(bankDetails));

      // Handle logo if present
      if (newCompany.logo instanceof File) {
        console.log('Appending logo file:', newCompany.logo.name);
        formData.append('logo', newCompany.logo);
      }

      const response = await axiosInstance.post('/api/companies', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      console.log('Company created successfully:', response.data);

      setSnackbar({
        open: true,
        message: 'Company added successfully',
        severity: 'success'
      });
      
      // Refresh dashboard stats
      fetchDashboardStats();
    } catch (error) {
      console.error('Error adding company:', error.response?.data || error);
      setSnackbar({
        open: true,
        message: error.response?.data?.message || 'Failed to add company',
        severity: 'error'
      });
    }
  };

  const handleAddProject = async (newProject) => {
    try {
      const formattedProject = {
        projectName: newProject.projectName,
        clientName: newProject.clientName,
        numberOfFiles: parseInt(newProject.numberOfFiles),
        unitPrice: parseFloat(newProject.unitPrice),
        projectStatus: newProject.projectStatus,
        paymentStatus: newProject.paymentStatus
      };

      const response = await axiosInstance.post('/api/projects', formattedProject);
      
      setSnackbar({
        open: true,
        message: 'Project added successfully',
        severity: 'success'
      });
      
      // Refresh dashboard stats
      fetchDashboardStats();
    } catch (error) {
      console.error('Error adding project:', error);
      setSnackbar({
        open: true,
        message: error.response?.data?.message || 'Failed to add project',
        severity: 'error'
      });
    }
  };

  const handleCloseSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  if (loading) {
    return (
      <div className="dashboard-loading">
        <CircularProgress size={40} thickness={3} />
        <div className="loading-text">Loading your dashboard...</div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="dashboard-container">
        <div className="dashboard-error">
          <h3>We encountered a problem</h3>
          <p>{error}</p>
          <button
            className="retry-button"
            onClick={handleRetry}
          >
            <RefreshIcon /> Retry
          </button>
          {process.env.NODE_ENV === 'development' && (
            <button
              className="retry-button"
              style={{ marginLeft: '10px', background: '#666' }}
              onClick={handleDebug}
            >
              <DebugIcon /> Debug
            </button>
          )}
        {debugInfo && (
            <div style={{ marginTop: '20px', padding: '12px', background: '#f5f5f5', borderRadius: '4px', overflowX: 'auto' }}>
              <pre style={{ fontSize: '0.8rem' }}>
                {JSON.stringify(debugInfo, null, 2)}
              </pre>
            </div>
        )}
        </div>
      </div>
    );
  }

  return (
    <div className="dashboard-container">
      <div className="dashboard-header">
        <h1 className="dashboard-title">Dashboard</h1>
        <p className="dashboard-subtitle">
          Welcome back, {user?.email || 'User'}! Here's an overview of your business performance.
        </p>
      </div>

      {/* Stats Cards */}
      <div className="stats-container">
        {/* Clients Card */}
        <StatCard 
          title="Total Clients" 
          value={stats?.clientsCount || 0}
          icon={<ClientIcon />}
          className="clients"
          subtitle="View all clients"
          onClick={() => navigate('/client-profiles')}
        />

        {/* Invoices Card */}
        <StatCard 
          title="Total Invoices" 
          value={stats?.invoicesCount || 0}
          icon={<InvoiceIcon />}
          className="invoices"
          subtitle="View all invoices"
          onClick={() => navigate('/all-invoices')}
        />

        {/* Projects Card */}
          <StatCard 
          title="Total Projects" 
          value={stats?.projectsCount || 0}
            icon={<ProjectsIcon />} 
          className="projects"
            subtitle="View all projects"
            onClick={() => navigate('/projects')}
          />

        {/* Revenue Card */}
          <StatCard 
          title="Total Revenue" 
          value={formatCurrency(stats?.totalRevenue || 0)}
          icon={<MoneyIcon />}
          className="revenue"
          subtitle={`${stats?.revenueChange > 0 ? '+' : ''}${stats?.revenueChange || 0}% from last month`}
        />
      </div>

      {/* Recent Invoices Section */}
      <div className="dashboard-section">
        <div className="section-header">
          <h2 className="section-title">Recent Invoices</h2>
          <Link to="/create-invoice" className="add-button">
            <AddIcon /> Create Invoice
          </Link>
        </div>
        
        {stats?.recentInvoices?.length > 0 ? (
          <div className="table-container">
            <table className="dashboard-table">
              <thead>
                <tr>
                  <th>Invoice #</th>
                  <th>Client</th>
                  <th>Amount</th>
                  <th>Date</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {stats.recentInvoices.map((invoice) => (
                  <tr key={invoice.id}>
                    <td>{invoice.invoice_number}</td>
                    <td>{invoice.client_name || 'N/A'}</td>
                    <td>{formatCurrency(invoice.total)}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <CalendarIcon style={{ fontSize: 16, color: '#667085' }} />
                        {formatDate(invoice.date)}
                      </div>
                    </td>
                    <td>
                      <span className={`status status-${invoice.status?.toLowerCase() || 'pending'}`}>
                        {invoice.status || 'Pending'}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <Link to={`/invoices/${invoice.id}`} className="action-button view-button">
                          <ViewOutlinedIcon style={{ fontSize: 16 }} /> View
                        </Link>
                        <Link to={`/edit-invoice/${invoice.id}`} className="action-button edit-button">
                          <EditIcon style={{ fontSize: 16 }} /> Edit
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="empty-state">
            <p>No invoices found. Create your first invoice to get started.</p>
            <Link to="/create-invoice" className="add-button">
              <AddIcon /> Create Invoice
            </Link>
          </div>
        )}
      </div>

      {/* Recent Projects Section */}
      <div className="dashboard-section">
        <div className="section-header">
          <h2 className="section-title">Recent Projects</h2>
          <button className="add-button" onClick={() => setIsAddProjectDialogOpen(true)}>
            <AddIcon /> Add Project
          </button>
        </div>
        
        {stats?.recentProjects?.length > 0 ? (
          <div className="table-container">
            <table className="dashboard-table">
              <thead>
                <tr>
                  <th>Project Name</th>
                  <th>Client</th>
                  <th>Start Date</th>
                  <th>Deadline</th>
                  <th>Status</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {stats.recentProjects.map((project) => (
                  <tr key={project.id}>
                    <td>{project.name}</td>
                    <td>{project.client_name || 'N/A'}</td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <CalendarIcon style={{ fontSize: 16, color: '#667085' }} />
                        {formatDate(project.start_date)}
                      </div>
                    </td>
                    <td>
                      <div style={{ display: 'flex', alignItems: 'center', gap: '6px' }}>
                        <CalendarIcon style={{ fontSize: 16, color: '#667085' }} />
                        {formatDate(project.deadline)}
                      </div>
                    </td>
                    <td>
                      <span className={`status status-${(project.status?.toLowerCase() || '').replace(' ', '-')}`}>
                        {project.status || 'Pending'}
                      </span>
                    </td>
                    <td>
                      <div className="action-buttons">
                        <Link to={`/projects?id=${project.id}`} className="action-button view-button">
                          <ViewOutlinedIcon style={{ fontSize: 16 }} /> View
                        </Link>
                        <Link to={`/projects?edit=${project.id}`} className="action-button edit-button">
                          <EditIcon style={{ fontSize: 16 }} /> Edit
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="empty-state">
            <p>No projects found. Add your first project to get started.</p>
            <button className="add-button" onClick={() => setIsAddProjectDialogOpen(true)}>
              <AddIcon /> Add Project
            </button>
          </div>
        )}
      </div>

      {/* Recent Clients Section */}
      <div className="dashboard-section">
        <div className="section-header">
          <h2 className="section-title">Recent Clients</h2>
          <button className="add-button" onClick={() => setIsAddClientDialogOpen(true)}>
            <AddIcon /> Add Client
          </button>
        </div>
        
        {stats?.recentClients?.length > 0 ? (
          <div className="table-container">
            <table className="dashboard-table">
              <thead>
                <tr>
                  <th>Client Name</th>
                  <th>Contact Person</th>
                  <th>Email</th>
                  <th>Phone</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {stats.recentClients.map((client) => (
                  <tr key={client.id}>
                    <td>{client.name}</td>
                    <td>{client.contactPerson || 'N/A'}</td>
                    <td>{client.email || 'N/A'}</td>
                    <td>{client.phone || 'N/A'}</td>
                    <td>
                      <div className="action-buttons">
                        <Link to={`/client-profiles?view=${client.id}`} className="action-button view-button">
                          <ViewOutlinedIcon style={{ fontSize: 16 }} /> View
                        </Link>
                        <Link to={`/client-profiles?edit=${client.id}`} className="action-button edit-button">
                          <EditIcon style={{ fontSize: 16 }} /> Edit
                        </Link>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        ) : (
          <div className="empty-state">
            <p>No clients found. Add your first client to get started.</p>
            <button className="add-button" onClick={() => setIsAddClientDialogOpen(true)}>
              <AddIcon /> Add Client
            </button>
          </div>
        )}
      </div>

      {/* Dialog components - keep unchanged */}
      <AddClientForm
        open={isAddClientDialogOpen}
        onClose={() => setIsAddClientDialogOpen(false)}
        onSubmit={handleAddClient}
      />
      
      <AddCompanyForm
        open={isAddCompanyDialogOpen}
        onClose={() => setIsAddCompanyDialogOpen(false)}
        onSubmit={handleAddCompany}
      />
      
      <AddProjectForm
        open={isAddProjectDialogOpen}
        onClose={() => setIsAddProjectDialogOpen(false)}
        onSubmit={handleAddProject}
      />
      
      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={handleCloseSnackbar}
      >
        <Alert onClose={handleCloseSnackbar} severity={snackbar.severity} sx={{ width: '100%' }}>
          {snackbar.message}
        </Alert>
      </Snackbar>
    </div>
  );
} 